def compile_ignore_patterns(pattern_list):
    compiled=[]
    for pat in pattern_list:
        if not pat:
            continue
        try:
            # Check if pattern valid regex
            re.compile(pat)
        except re.error as e:
            print(f"Error: error parsing regexp: {e}: `{pat}`", file=sys.stderr)
            sys.exit(1)
        # For matching, we will use "^" + pat
        try:
            # compile with ^ anchor
            cre = re.compile("^" + pat)
