def check_time_filter(mtime, since_dt, since_is_date, until_dt, until_is_date, max_age_sec, min_age_sec):
    # mtime is int timestamp (seconds)
    # Convert to datetime UTC
    mt = datetime.datetime.fromtimestamp(mtime, tz=datetime.timezone.utc)
    now = datetime.datetime.now(datetime.timezone.utc)

    if since_dt is not None:
        if since_is_date:
            # Since date only: includes whole day, so since_dt is start of day 00:00
            # Include if mt >= start of day
