def build_json_structure(node, show_apparent):
    # node is dir
    # Returns list structure as per gdu JSON
    # First element dict with name, mtime, maybe?
    # For root, name is full path
    # For subdir, name is basename
    # JSON structure: list where first element is dict {"name":..., "mtime":...}
    # Then file dicts and dir lists
    # File dict: {"name":..., "asize":..., "dsize":..., "mtime":..., "ino":..., "hlnkc":true, "notreg":true}
    # asize and dsize only if non-zero? In earlier JSON, empty file had no asize/dsize, just mtime. File with size 1 and blocks 0 had asize 1 but no dsize.
    # So include asize if !=0? Actually file with 0 size had no asize. So include asize if !=0.
    # Include dsize if has_dsize and !=0? For file with size 1 and blocks 0, dsize missing. So include dsize if has_dsize.
    # For symlink not followed: asize = len(target), mtime, notreg true, no dsize
    # For hardlink: include ino and hlnkc true, plus asize/dsize for all occurrences? In JSON, all hardlink occurrences had full asize/dsize and ino and hlnkc true.
    # So for JSON, we should NOT deduplicate hardlinks; we should include full sizes for all.
    # But our Node for second hardlink occurrence currently has size 0. For JSON we need to keep original sizes.
    # We need to handle that separately.

    lst=[]
    d={}
    d["name"]=node.name
    d["mtime"]=node.mtime
    lst.append(d)
    for child in node.children:
        if child.is_dir:
            sub = build_json_structure(child, show_apparent)
            lst.append(sub)
        else:
            fd={}
            fd["name"]=child.name
            # asize
            # For symlink not followed, asize = len(target) which is stored in asize?
            # For file, asize is file size
            # Include asize if !=0
            if child.asize !=0:
                fd["asize"]=child.asize
            if child.has_dsize and child.dsize!=0:
                fd["dsize"]=child.dsize
            fd["mtime"]=child.mtime
            if child.has_ino and child.ino!=0:
                fd["ino"]=child.ino
                fd["hlnkc"]=True
            if child.flag=='@':
                fd["notreg"]=True
            lst.append(fd)
    return lst

