        nodes[id_] = (node, parent_id)
        if parent_id is None:
            root = node
    # Now build tree via parent_id
    for id_, (node, parent_id) in nodes.items():
        if parent_id is not None and parent_id in nodes:
            parent_node = nodes[parent_id][0]
            parent_node.children.append(node)

    # For full_path reconstruction, set root full_path to top_path
    if root:
        root.full_path = top_path
        # Recursively set children's full_path?
        def set_full_path(node, base):
            for child in node.children:
                child.full_path = os.path.join(base, child.name)
                if child.is_dir:
