def check_time_filter(mtime, since_dt, since_is_date, until_dt, until_is_date, max_age_sec, min_age_sec):
    # mtime is int timestamp (seconds)
    # Convert to datetime UTC
    mt = datetime.datetime.fromtimestamp(mtime, tz=datetime.timezone.utc)
    now = datetime.datetime.now(datetime.timezone.utc)

    if since_dt is not None:
        if since_is_date:
            # Since date only: includes whole day, so since_dt is start of day 00:00
            # Include if mt >= start of day
            # Actually "calendar-day compare; includes the whole day" means for date only, compare calendar day ignoring time?
            # For since, if file mtime date is >= since date (calendar day), include
            # That is equivalent to mt.date() >= since_dt.date() ?
            # But since_dt is at 00:00 UTC, mt >= since_dt would include whole day? For file at same day any time, mt >= 00:00 true, so include.
            # For file at previous day, mt < start, exclude.
            # So we can check mt >= since_dt (start of day)
            if mt < since_dt:
                return False
        else:
            # RFC3339 timestamp: mt >= since_dt
            if mt < since_dt:
                return False
    if until_dt is not None:
        if until_is_date:
            # until date only: includes whole day, so until end of day 23:59:59.999
            # So until_dt is start of day, we need end of day
            end_of_day = until_dt + datetime.timedelta(days=1) - datetime.timedelta(microseconds=1)
            if mt > end_of_day:
                return False
        else:
            if mt > until_dt:
                return False
    if max_age_sec is not None:
        # max-age: include if age < duration, i.e., mtime >= now - duration
        # But based on earlier tests, it's < not <=
        # So age = now - mt, include if age < max_age_sec
        # Actually we observed age == duration excluded, so < 
        cutoff = now - datetime.timedelta(seconds=max_age_sec)
        # mt must be > cutoff? Since age < duration => now - mt < duration => mt > now - duration
        # But we observed age 0 with max-age 1s included, age 1s with max-age 1s excluded => age < duration, so mt > cutoff? For age 0, mt = now, cutoff = now -1s, mt > cutoff true => include. For age 1s, mt = now-1s, cutoff = now-1s, mt > cutoff false (equal not >) => exclude. So need >
        if mt <= cutoff:
            return False
    if min_age_sec is not None:
        # min-age: include if age >= duration, i.e., mt <= now - duration
        cutoff = now - datetime.timedelta(seconds=min_age_sec)
        # mt <= cutoff inclusive? We observed age 1s with min-age 1s included, so >= includes equal
        if mt > cutoff:
            return False
    return True

