def json_to_node(data_root_list, base_path=""):
    # data_root_list is like [{"name":"/tmp/...","mtime":...}, file dicts, [subdir...]]
    # Convert to Node tree
    if not data_root_list or not isinstance(data_root_list, list):
        return None
    header_dict = data_root_list[0]
    name = header_dict.get("name","")
    mtime = header_dict.get("mtime", int(time.time()))
    full_path = name if os.path.isabs(name) else os.path.join(base_path, name) if base_path else name
    node = Node(name=name, full_path=full_path, is_dir=True, mtime=mtime, flag=' ')
    children=[]
    total_apparent=DIR_OWN_SIZE
    total_disk=DIR_OWN_SIZE
    total_count=1
    for item in data_root_list[1:]:
        if isinstance(item, dict):
            # file
            fname = item.get("name","")
            fpath = os.path.join(full_path, fname)
            asize = item.get("asize",0)
            dsize = item.get("dsize",0)
            has_dsize = "dsize" in item
            mtime_f = item.get("mtime", int(time.time()))
            ino = item.get("ino",0)
            has_ino = "ino" in item
            notreg = item.get("notreg",False)
            flag='@' if notreg else ' '
            # For hardlink, flag? In json, all hardlink occurrences had flag? Actually json doesn't have flag, but has hlnkc.
            # In non-interactive listing for json imported, we saw no H flags? Let's check for hardlink json import.
            # Earlier for hard2 json import, what would listing show? We didn't test. But for now, if has_ino and hlnkc, we could treat as hardlink but for json we keep full size.
            child = Node(name=fname, full_path=fpath, is_dir=False, mtime=mtime_f, asize=asize, dsize=dsize, has_dsize=has_dsize, ino=ino, has_ino=has_ino, flag=flag)
            child.apparent_total = asize
            child.disk_total = dsize if has_dsize else 0
            child.item_count = 1
            children.append(child)
            total_apparent+=asize
            total_disk+= (dsize if has_dsize else 0)
            total_count+=1
        elif isinstance(item, list):
            sub_node = json_to_node(item, base_path=full_path)
            if sub_node:
                children.append(sub_node)
                total_apparent+=sub_node.apparent_total
                total_disk+=sub_node.disk_total
                total_count+=sub_node.item_count
    node.children=children
    node.apparent_total=total_apparent
    node.disk_total=total_disk
    node.item_count=total_count
    # Flag e if empty?
    if not children:
        # Check if original dir was empty? In JSON, empty dir is list with single dict, no children, so children empty -> flag e?
        node.flag='e'
    return node

def save_to_sqlite(db_path, root_node):
    # Remove existing file if exists
    try:
        if os.path.exists(db_path):
            os.remove(db_path)
    except:
        pass
    # Handle directory removal if badger?
    # For sqlite, db_path is file

    con = sqlite3.connect(db_path)
    cur = con.cursor()
    cur.execute("CREATE TABLE items (\n\t\tid          INTEGER PRIMARY KEY,\n\t\tparent_id   INTEGER REFERENCES items(id),\n\t\tname        TEXT NOT NULL,\n\t\tis_dir      INTEGER NOT NULL,\n\t\tsize        INTEGER NOT NULL,\n\t\tusage       INTEGER NOT NULL,\n\t\tmtime       INTEGER NOT NULL,\n\t\titem_count  INTEGER NOT NULL DEFAULT 1,\n\t\tmli         INTEGER NOT NULL DEFAULT 0,\n\t\tflag        TEXT NOT NULL DEFAULT ' '\n\t)")
    cur.execute("CREATE INDEX idx_items_parent_id ON items(parent_id)")
    cur.execute("CREATE INDEX idx_items_mli ON items(mli) WHERE mli != 0")
    cur.execute("CREATE TABLE metadata (\n\t\tkey   TEXT PRIMARY KEY,\n\t\tvalue TEXT\n\t)")

    # Insert metadata
    cur.execute("INSERT INTO metadata (key,value) VALUES (?,?)", ("top_dir_path", root_node.full_path))

    # Now insert items recursively
    # Need to track id
    next_id=1
    # Use stack

    def insert_node(node, parent_id):
        nonlocal next_id
        cur_id = next_id
        next_id+=1
        is_dir_int = 1 if node.is_dir else 0
        size = node.apparent_total if node.is_dir else node.asize  # For file, size is asize? In earlier db, size was asize for files, and for dirs size was apparent total
        usage = node.disk_total if node.is_dir else (node.dsize if node.has_dsize else 0)  # For file, usage is dsize if has, else 0
        # For dir, size and usage are totals as computed
        # For file that is hardlink second occurrence, size and usage should be 0 per db observation for second occurrence
        # But our node for second hardlink has size 0 already (apparent_total 0) and disk_total 0, so size will be 0
        # For file first occurrence, size asize, usage dsize

        # For mtime, use node.mtime
        # item_count
        # mli is ino if has_ino else 0? In earlier db, for first hardlink file, mli was ino (35178487) ? Let's see: earlier for hardacross.db, first file had mli 35178487? Actually we had (3,2,'file',0,6,4096,..,1,35178487,' ') - mli is 35178487, which equals ino. For second hardlink file, mli also 35178487. For non-hardlink files, mli 0.
        # So mli = ino if has_ino else 0
        mli = node.ino if node.has_ino else 0
        flag = node.flag

        cur.execute("INSERT INTO items (id,parent_id,name,is_dir,size,usage,mtime,item_count,mli,flag) VALUES (?,?,?,?,?,?,?,?,?,?)",
                    (cur_id, parent_id, node.name, is_dir_int, size, usage, node.mtime, node.item_count, mli, flag))
        if node.is_dir:
            for child in node.children:
                insert_node(child, cur_id)

    insert_node(root_node, None)
    con.commit()
    con.close()

def load_from_sqlite(db_path):
    # Load db and reconstruct Node? For reading mode, we need to show listing similar to original when reading from storage.
    # Original when reading from db with -r and -n gave listing of children? Actually earlier when reading from db with -r -n /tmp/testdir it gave listing of /sub1 etc (children). So it should reconstruct tree.

    con = sqlite3.connect(db_path)
    cur = con.cursor()
    try:
        cur.execute("SELECT value FROM metadata WHERE key='top_dir_path'")
        row = cur.fetchone()
        top_path = row[0] if row else "/"
    except:
        top_path = "/"

    cur.execute("SELECT id,parent_id,name,is_dir,size,usage,mtime,item_count,mli,flag FROM items ORDER BY id")
    rows = cur.fetchall()
    # Build dict id->node
    nodes={}
    root=None
    for r in rows:
        id_,parent_id,name,is_dir,size,usage,mtime,item_count,mli,flag = r
        is_dir_bool = bool(is_dir)
        node = Node(name=name, full_path="", is_dir=is_dir_bool, mtime=mtime, flag=flag)
        node.apparent_total = size
        node.disk_total = usage
        node.item_count = item_count
        node.ino = mli
        node.has_ino = mli!=0
        node.asize = size if not is_dir_bool else 0
        node.dsize = usage if not is_dir_bool else 0
        node.has_dsize = True if usage!=0 or (not is_dir_bool and size!=0) else False
        # For files, if size 0 and usage 0, has_dsize False? Let's check earlier: for empty file, db had size 0, usage 0, flag ' '. So has_dsize should be False for that? But we will keep True? Actually for empty file, dsize missing in json, but in db usage 0. So has_dsize maybe True even if 0? In previous db for empty file, we had (5,1,'emptyfile',0,0,0,..,1,0,' ') - size 0, usage 0. So has_dsize? Could be True? But earlier file with truncate 1 byte and blocks 0 had size 1, usage 0? Actually we had file d size 1, usage 0? Let's not overcomplicate.

        nodes[id_] = (node, parent_id)
        if parent_id is None:
            root = node
    # Now build tree via parent_id
    for id_, (node, parent_id) in nodes.items():
        if parent_id is not None and parent_id in nodes:
            parent_node = nodes[parent_id][0]
            parent_node.children.append(node)

    # For full_path reconstruction, set root full_path to top_path
    if root:
        root.full_path = top_path
        # Recursively set children's full_path?
        def set_full_path(node, base):
            for child in node.children:
                child.full_path = os.path.join(base, child.name)
                if child.is_dir:
                    set_full_path(child, child.full_path)
        set_full_path(root, root.full_path)

    con.close()
    return root

def list_devices():
    # Parse /proc/mounts
    mounts=[]
    try:
        with open('/proc/mounts','r') as f:
            for line in f:
                parts=line.split()
                if len(parts)<4:
                    continue
                device=parts[0]
                mountpoint=parts[1]
                fstype=parts[2]
                # Filter? Original only shows certain? It showed only /dev/nvme0n1 mounts for /etc/... in container. But also would show other mounts? Let's see df output shows overlay etc. But original's output for -d showed only /dev/nvme0n1 mounts, not overlay, tmpfs, etc. Why? Perhaps it filters to only show disks with non-zero size? Or only shows mounts where device is block device?
                # For simplicity, we will include all mounts where we can statfs, but we will filter similar to original? The original showed only /dev/nvme0n1 mounts, not overlay root. Could be because overlay has device "overlay" not block device, and they filter to only block devices? Or they show all mounted disks but in container only /dev/nvme0n1 is block device?
                # Let's implement: include mounts where device starts with "/dev/" or is block device? We'll include all where device starts with "/dev/".
                # In /proc/mounts we have /dev/nvme0n1 for 3 entries. So that matches.
                # Also include overlay if it's root? But original didn't show overlay. So filter to /dev/* only.
                if not device.startswith('/dev/'):
                    continue
                mounts.append((device, mountpoint))
    except:
        pass
    # For each mount, get statfs
    results=[]
    for dev, mp in mounts:
        try:
            st = os.statvfs(mp)
            # Total blocks * frsize
            total = st.f_blocks * st.f_frsize
            free = st.f_bfree * st.f_frsize
            avail = st.f_bavail * st.f_frsize
            used = total - free
            results.append((dev, total, used, free, mp))
        except:
            continue
    return results

