                    flags['summarize']=True
                    j+=1
                elif ch=='L':
                    flags['follow-symlinks']=True
                    j+=1
                elif ch in ('D','E','i','I','X','f','l','m','o','t','T'):
                    remaining=chars[j+1:]
                    if remaining:
                        val=remaining
                        if val.startswith('='):
                            val=val[1:]
                        if ch=='D':
                            flags['db']=val
                        elif ch=='E':
                            if val:
                                flags['exclude-type'].extend([x for x in val.split(',') if x!=''])
                        elif ch=='i':
                            if val=="":
                                flags['ignore-dirs']=[]
                            else:
                                if flags['ignore-dirs'] is None:
                                    flags['ignore-dirs']=[]
                                flags['ignore-dirs'].extend([x for x in val.split(',') if x!=''])
                        elif ch=='I':
                            if val:
                                flags['ignore-dirs-pattern'].extend([x for x in val.split(',') if x!=''])
                        elif ch=='X':
                            flags['ignore-from']=val
                        elif ch=='f':
                            flags['input-file']=val
                        elif ch=='l':
                            flags['log-file']=val
                        elif ch=='m':
                            try:
                                flags['max-cores']=int(val)
                            except:
                                print(f"Error: invalid argument \"{val}\" for \"-m, --max-cores\" flag: strconv.ParseInt: parsing \"{val}\": invalid syntax", file=sys.stderr)
                                sys.exit(1)
                        elif ch=='o':
                            flags['output-file']=val
                        elif ch=='t':
                            try:
                                flags['top']=int(val)
                            except:
                                print(f"Error: invalid argument \"{val}\" for \"-t, --top\" flag: strconv.ParseInt: parsing \"{val}\": invalid syntax", file=sys.stderr)
                                sys.exit(1)
                        elif ch=='T':
                            if val:
                                flags['type'].extend([x for x in val.split(',') if x!=''])
                        j=len(chars)
                    else:
                        i+=1
                        if i>=len(argv):
                            print(f"Error: flag needs an argument: '-{ch}' in -{ch}", file=sys.stderr)
                            sys.exit(1)
                        val=argv[i]
                        if ch=='D':
                            flags['db']=val
                        elif ch=='E':
                            if val:
                                flags['exclude-type'].extend([x for x in val.split(',') if x!=''])
                        elif ch=='i':
                            if val=="":
                                flags['ignore-dirs']=[]
                            else:
                                if flags['ignore-dirs'] is None:
                                    flags['ignore-dirs']=[]
                                flags['ignore-dirs'].extend([x for x in val.split(',') if x!=''])
                        elif ch=='I':
                            if val:
                                flags['ignore-dirs-pattern'].extend([x for x in val.split(',') if x!=''])
                        elif ch=='X':
                            flags['ignore-from']=val
                        elif ch=='f':
                            flags['input-file']=val
                        elif ch=='l':
                            flags['log-file']=val
                        elif ch=='m':
                            try:
                                flags['max-cores']=int(val)
                            except:
                                print(f"Error: invalid argument \"{val}\" for \"-m, --max-cores\" flag: strconv.ParseInt: parsing \"{val}\": invalid syntax", file=sys.stderr)
                                sys.exit(1)
                        elif ch=='o':
                            flags['output-file']=val
                        elif ch=='t':
                            try:
                                flags['top']=int(val)
                            except:
                                print(f"Error: invalid argument \"{val}\" for \"-t, --top\" flag: strconv.ParseInt: parsing \"{val}\": invalid syntax", file=sys.stderr)
                                sys.exit(1)
                        elif ch=='T':
                            if val:
                                flags['type'].extend([x for x in val.split(',') if x!=''])
                        j+=1
                        break
                else:
                    print(f"Error: unknown shorthand flag: '{ch}' in -{ch}", file=sys.stderr)
                    sys.exit(1)
        else:
            positional.append(arg)
        i+=1
    if flags['ignore-dirs'] is None:
        flags['ignore-dirs'] = ['/proc','/dev','/sys','/run']
    return flags, positional

class Node:
    def __init__(self, name, full_path, is_dir, mtime, asize=0, dsize=0, has_dsize=True, ino=0, has_ino=False, flag=' ', children=None):
        self.name=name
        self.full_path=full_path
        self.is_dir=is_dir
        self.mtime=mtime
        self.asize=asize
        self.dsize=dsize
        self.has_dsize=has_dsize
        self.ino=ino
        self.has_ino=has_ino
        self.flag=flag
        self.children=children if children is not None else []
        self.apparent_total=0
        self.disk_total=0
        self.item_count=1

def parse_yaml_with_lists(path):
    try:
        with open(path,'r') as f:
            lines=f.readlines()
    except FileNotFoundError:
        raise
    data={}
    stack=[(-1,data,None)]
    last_list_key=None
    for raw in lines:
        if not raw.strip() or raw.strip().startswith('#'):
            continue
        indent=len(raw)-len(raw.lstrip(' '))
        stripped=raw.strip()
        if stripped.startswith('- '):
            item=stripped[2:].strip()
            if item.startswith("'") and item.endswith("'"):
                item=item[1:-1]
            elif item.startswith('"') and item.endswith('"'):
                item=item[1:-1]
            while stack and stack[-1][0]>=indent:
                stack.pop()
            if not stack:
                continue
            parent_dict=stack[-1][1]
            if last_list_key and last_list_key in parent_dict and isinstance(parent_dict[last_list_key], list):
                parent_dict[last_list_key].append(item)
            continue
        if ':' not in stripped:
            continue
        key,val = stripped.split(':',1)
        key=key.strip()
        val=val.strip()
        while stack and stack[-1][0]>=indent:
            stack.pop()
        parent = stack[-1][1] if stack else data
        if val=="":
            if key in ("ignore-dirs","ignore-dir-patterns","type","exclude-type"):
                parent[key]=[]
                last_list_key=key
                stack.append((indent,parent,key))
            else:
                new_dict={}
                parent[key]=new_dict
                stack.append((indent,new_dict,None))
                last_list_key=None
        else:
            if val.startswith("'") and val.endswith("'"):
                val=val[1:-1]
            elif val.startswith('"') and val.endswith('"'):
                val=val[1:-1]
            if val.lower()=="true":
                parent[key]=True
            elif val.lower()=="false":
                parent[key]=False
            else:
                try:
                    if re.fullmatch(r'-?\d+', val):
                        parent[key]=int(val)
                    else:
                        parent[key]=val
                except:
                    parent[key]=val
    return data

def load_config(config_path_arg):
    cfg={}
    cfg_path=""
    if config_path_arg:
        cfg_path=config_path_arg
        try:
            cfg=parse_yaml_with_lists(cfg_path)
        except FileNotFoundError:
            cfg={}
        return cfg, cfg_path
    else:
        home=os.path.expanduser("~")
        p1=os.path.join(home,".config","gdu","gdu.yaml")
        p2=os.path.join(home,".gdu.yaml")
        for p in (p1,p2):
            try:
                cfg=parse_yaml_with_lists(p)
                return cfg, p
            except FileNotFoundError:
                continue
        return {}, p2

