        size_str = str(size_val) if flags['no-prefix'] else (format_size_kib(size_val, flags['si']) if flags['show-in-kib'] else format_size_human(size_val, flags['si']))
        # Name: for dirs, "/dirname" with leading slash, for files just basename?
