        nodes=[]
        def gather(node, cur_depth):
            if cur_depth>flags['depth']:
                return
            nodes.append(node)
            if node.is_dir:
                for child in node.children:
                    if child.is_dir:
                        gather(child, cur_depth+1)
                    else:
                        if cur_depth+1 <= flags['depth']:
