        gather(root_node, 0)
        if nodes:
            root = nodes[0]
            rest = nodes[1:]
            def sz2(n):
                if n.is_dir:
                    return n.apparent_total if flags['show-apparent-size'] else n.disk_total
                else:
                    return n.asize if flags['show-apparent-size'] else (n.dsize if n.has_dsize else 0)
            # For depth, root always first, then rest sorted
            rest.sort(key=lambda x: (sz2(x), x.name), reverse=not flags['reverse-sort'])
            sorted_nodes = [root] + rest
        else:
            sorted_nodes=[]
        for n in sorted_nodes:
            if n.is_dir:
                size_val = n.apparent_total if flags['show-apparent-size'] else n.disk_total
            else:
                size_val = n.asize if flags['show-apparent-size'] else (n.dsize if n.has_dsize else 0)
            print(format_line_no_flag(size_val, flags['si'], flags['show-in-kib'], flags['no-prefix'], n.full_path))
        sys.exit(0)

    # Default
    children = root_node.children
    def sz3(c):
        if c.is_dir:
            return c.apparent_total if flags['show-apparent-size'] else c.disk_total
        else:
            return c.asize if flags['show-apparent-size'] else (c.dsize if c.has_dsize else 0)
