class Node:
    def __init__(self, name, full_path, is_dir, mtime, asize=0, dsize=0, has_dsize=True, ino=0, has_ino=False, flag=' ', children=None):
        self.name=name
        self.full_path=full_path
        self.is_dir=is_dir
        self.mtime=mtime
        self.asize=asize
        self.dsize=dsize
        self.has_dsize=has_dsize
        self.ino=ino
        self.has_ino=has_ino
