def parse_yaml_with_lists(path):
    try:
        with open(path,'r') as f:
            lines=f.readlines()
    except FileNotFoundError:
        raise
    data={}
    stack=[(-1,data,None)]
    last_list_key=None
    for raw in lines:
        if not raw.strip() or raw.strip().startswith('#'):
            continue
        indent=len(raw)-len(raw.lstrip(' '))
        stripped=raw.strip()
        if stripped.startswith('- '):
            item=stripped[2:].strip()
            if item.startswith("'") and item.endswith("'"):
                item=item[1:-1]
            elif item.startswith('"') and item.endswith('"'):
                item=item[1:-1]
            while stack and stack[-1][0]>=indent:
                stack.pop()
            if not stack:
                continue
            parent_dict=stack[-1][1]
            if last_list_key and last_list_key in parent_dict and isinstance(parent_dict[last_list_key], list):
                parent_dict[last_list_key].append(item)
            continue
        if ':' not in stripped:
            continue
        key,val = stripped.split(':',1)
        key=key.strip()
        val=val.strip()
        while stack and stack[-1][0]>=indent:
            stack.pop()
        parent = stack[-1][1] if stack else data
        if val=="":
            if key in ("ignore-dirs","ignore-dir-patterns","type","exclude-type"):
                parent[key]=[]
                last_list_key=key
                stack.append((indent,parent,key))
            else:
                new_dict={}
                parent[key]=new_dict
                stack.append((indent,new_dict,None))
                last_list_key=None
        else:
            if val.startswith("'") and val.endswith("'"):
                val=val[1:-1]
            elif val.startswith('"') and val.endswith('"'):
                val=val[1:-1]
            if val.lower()=="true":
                parent[key]=True
            elif val.lower()=="false":
                parent[key]=False
            else:
                try:
                    if re.fullmatch(r'-?\d+', val):
                        parent[key]=int(val)
                    else:
                        parent[key]=val
                except:
                    parent[key]=val
    return data

def load_config(config_path_arg):
    cfg={}
    cfg_path=""
    if config_path_arg:
        cfg_path=config_path_arg
        try:
            cfg=parse_yaml_with_lists(cfg_path)
        except FileNotFoundError:
            cfg={}
        return cfg, cfg_path
    else:
        home=os.path.expanduser("~")
        p1=os.path.join(home,".config","gdu","gdu.yaml")
        p2=os.path.join(home,".gdu.yaml")
        for p in (p1,p2):
            try:
                cfg=parse_yaml_with_lists(p)
                return cfg, p
            except FileNotFoundError:
                continue
        return {}, p2

def write_config_file(path, flags):
    dir_path=os.path.dirname(path)
    if dir_path and not os.path.exists(dir_path):
        try:
            with open(path,'w'):
                pass
            os.remove(path)
        except FileNotFoundError:
            raise IOError(f"open {path}: no such file or directory")
        except PermissionError:
            raise IOError(f"open {path}: permission denied")
    try:
        with open(path,'w') as f:
            f.write("style:\n")
            f.write("    footer:\n")
            f.write("        text-color: '#000000'\n")
            f.write("        background-color: '#2479D0'\n")
            f.write("        number-color: '#FFFFFF'\n")
            f.write("    selected-row:\n")
            f.write("        text-color: \"\"\n")
            f.write("        background-color: \"\"\n")
            f.write("    result-row:\n")
            f.write("        number-color: '#e67100'\n")
            f.write("        directory-color: '#3498db'\n")
            f.write("    header:\n")
            f.write("        text-color: '#000000'\n")
            f.write("        background-color: '#2479D0'\n")
            f.write("        hidden: false\n")
            f.write("    progress-modal:\n")
            f.write("        current-item-path-max-len: 0\n")
            f.write("    use-old-size-bar: false\n")
            f.write("sorting:\n")
            f.write("    by: \"\"\n")
            f.write("    order: \"\"\n")
            def get(k, default):
                return flags.get(k, default)
            f.write(f"log-file: {get('log-file','/dev/null')}\n")
            f.write(f"input-file: \"{get('input-file','')}\"\n")
            f.write(f"output-file: \"{get('output-file','')}\"\n")
            f.write(f"ignore-from-file: \"{get('ignore-from-file','')}\"\n")
            ignore_dirs=get('ignore-dirs',['/proc','/dev','/sys','/run'])
            f.write("ignore-dirs:\n")
            for d in ignore_dirs:
                f.write(f"    - {d}\n")
            ig_patterns=get('ignore-dir-patterns',[])
            if ig_patterns:
                f.write("ignore-dir-patterns:\n")
                for pat in ig_patterns:
                    f.write(f"    - {pat}\n")
            else:
                f.write("ignore-dir-patterns: []\n")
            type_list=get('type',[])
            if type_list:
                f.write("type:\n")
                for t in type_list:
