            log_fh.write(f'time="{ts}" level=info msg="Error reading config file: open {default_cfg_path}: no such file or directory"\n')
        elif flags['config-file'] and not os.path.exists(flags['config-file']):
            ts=datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
            log_fh.write(f'time="{ts}" level=info msg="Error reading config file: open {flags["config-file"]}: no such file or directory"\n')
        ts=datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        ignore_dirs_str=" ".join(flags['ignore-dirs'])
        ignore_patterns_str=" ".join(flags['ignore-dirs-pattern'])
