def get_help_text():
    return HELP_TEXT.format(cores=CORES)

def format_size_human(size, si=False):
    if si:
        if size < 1000:
            return f"{size} B"
        units = ["kB", "MB", "GB", "TB", "PB", "EB"]
        v = float(size)
        idx=-1
        while v >= 1000 and idx < len(units)-1:
            v/=1000
            idx+=1
        return f"{v:.1f} {units[idx]}"
    else:
        if size < 1024:
            return f"{size} B"
        units = ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB"]
        v=float(size)
        idx=-1
        while v>=1024 and idx < len(units)-1:
            v/=1024
            idx+=1
        return f"{v:.1f} {units[idx]}"

def format_size_kib(size, si=False):
    if si:
        v=size/1000.0
        return f"{v:.1f} kB"
    else:
        v=size/1024.0
        return f"{v:.1f} KiB"

def format_line_with_flag(flag, size_val, si, kib, no_prefix, name):
    if no_prefix:
        size_str = f"{size_val}"
    else:
        if kib:
            size_str = format_size_kib(size_val, si)
        else:
            size_str = format_size_human(size_val, si)
    w = max(10, len(size_str)+1)
    return f"{flag}{size_str:>{w}} {name}"

def format_line_no_flag(size_val, si, kib, no_prefix, name):
    if no_prefix:
        size_str = f"{size_val}"
    else:
        if kib:
            size_str = format_size_kib(size_val, si)
        else:
            size_str = format_size_human(size_val, si)
    w = max(9, len(size_str))
    return f"{size_str:>{w}} {name}"

def parse_duration(s):
    if not s:
        raise ValueError(f'invalid duration format "{s}". Use combinations like 7d, 2h30m, 1y2mo')
    pattern = re.compile(r'(?P<value>\d+)(?P<unit>y|mo|w|d|h|m|s)')
    pos=0
    total=0
    found=False
    while pos < len(s):
        m=pattern.match(s,pos)
        if not m:
            raise ValueError(f'invalid duration format "{s}". Use combinations like 7d, 2h30m, 1y2mo')
        val=int(m.group('value'))
        unit=m.group('unit')
        found=True
        if unit=='y':
            total+=val*365*86400
        elif unit=='mo':
            total+=val*30*86400
        elif unit=='w':
            total+=val*7*86400
        elif unit=='d':
            total+=val*86400
        elif unit=='h':
            total+=val*3600
        elif unit=='m':
            total+=val*60
        elif unit=='s':
            total+=val
        pos=m.end()
    if not found:
        raise ValueError(f'invalid duration format "{s}". Use combinations like 7d, 2h30m, 1y2mo')
    return total

def parse_since_until(s):
    try:
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
            dt = datetime.datetime.strptime(s, "%Y-%m-%d")
            dt = dt.replace(tzinfo=datetime.timezone.utc)
            return (dt, True)
        iso = s.replace('Z','+00:00')
        dt = datetime.datetime.fromisoformat(iso)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return (dt, False)
    except Exception:
        raise ValueError(f'invalid time value "{s}". Use RFC3339 timestamp or YYYY-MM-DD')

