        units = ["kB", "MB", "GB", "TB", "PB", "EB"]
        v = float(size)
        idx=-1
        while v >= 1000 and idx < len(units)-1:
            v/=1000
            idx+=1
        return f"{v:.1f} {units[idx]}"
    else:
        if size < 1024:
            return f"{size} B"
        units = ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB"]
        v=float(size)
