        'archive-browsing': False,
        'collapse-path': False,
        'config-file': '',
        'db': '',
        'depth': 0,
        'enable-profiling': False,
        'exclude-type': [],
        'follow-symlinks': False,
        'help': False,
        'ignore-dirs': None,
        'ignore-dirs-pattern': [],
        'ignore-from': '',
        'input-file': '',
        'log-file': '/dev/null',
        'max-age': '',
        'max-cores': CORES,
        'min-age': '',
        'mouse': False,
        'no-color': False,
        'no-cross': False,
        'no-delete': False,
        'no-hidden': False,
        'no-prefix': False,
        'no-progress': False,
        'no-spawn-shell': False,
        'no-unicode': False,
        'non-interactive': False,
        'output-file': '',
        'read-from-storage': False,
        'reverse-sort': False,
        'sequential': False,
        'show-annexed-size': False,
        'show-apparent-size': False,
        'show-disks': False,
        'show-in-kib': False,
        'show-item-count': False,
        'show-mtime': False,
        'show-relative-size': False,
        'si': False,
        'since': '',
        'summarize': False,
        'top': 0,
        'type': [],
        'until': '',
        'version': False,
        'write-config': False,
    }
    positional=[]
    i=0
    while i < len(argv):
        arg=argv[i]
        if arg=='--':
            positional.extend(argv[i+1:])
            break
        if arg.startswith('--'):
            if '=' in arg:
                name,val = arg.split('=',1)
            else:
                name=arg
                val=None
            def need_val():
                nonlocal i,val
                if val is None:
                    i+=1
                    if i>=len(argv):
                        print(f"Error: flag needs an argument: {name}", file=sys.stderr)
                        sys.exit(1)
                    val=argv[i]
                return val
            if name=='--config-file':
                flags['config-file']=need_val()
            elif name=='--db':
                flags['db']=need_val()
            elif name=='--depth':
                v=need_val()
                try:
                    flags['depth']=int(v)
                except:
                    print(f"Error: invalid argument \"{v}\" for \"--depth\" flag: strconv.ParseInt: parsing \"{v}\": invalid syntax", file=sys.stderr)
                    sys.exit(1)
            elif name=='--exclude-type':
                v=need_val()
                if v:
                    flags['exclude-type'].extend([x for x in v.split(',') if x!=''])
            elif name=='--ignore-dirs':
                v=need_val()
                if v=="":
                    flags['ignore-dirs']=[]
                else:
                    if flags['ignore-dirs'] is None:
                        flags['ignore-dirs']=[]
                    flags['ignore-dirs'].extend([x for x in v.split(',') if x!=''])
            elif name=='--ignore-dirs-pattern':
                v=need_val()
                if v:
                    flags['ignore-dirs-pattern'].extend([x for x in v.split(',') if x!=''])
            elif name=='--ignore-from':
                flags['ignore-from']=need_val()
            elif name=='--input-file':
                flags['input-file']=need_val()
            elif name=='--log-file':
                flags['log-file']=need_val()
            elif name=='--max-age':
                flags['max-age']=need_val()
            elif name=='--max-cores':
                v=need_val()
                try:
                    flags['max-cores']=int(v)
                except:
                    print(f"Error: invalid argument \"{v}\" for \"-m, --max-cores\" flag: strconv.ParseInt: parsing \"{v}\": invalid syntax", file=sys.stderr)
                    sys.exit(1)
            elif name=='--min-age':
                flags['min-age']=need_val()
            elif name=='--output-file':
                flags['output-file']=need_val()
            elif name=='--since':
                flags['since']=need_val()
            elif name=='--until':
                flags['until']=need_val()
            elif name=='--top':
                v=need_val()
                try:
                    flags['top']=int(v)
                except:
                    print(f"Error: invalid argument \"{v}\" for \"-t, --top\" flag: strconv.ParseInt: parsing \"{v}\": invalid syntax", file=sys.stderr)
                    sys.exit(1)
            elif name=='--type':
                v=need_val()
                if v:
                    flags['type'].extend([x for x in v.split(',') if x!=''])
            elif name=='--archive-browsing':
                flags['archive-browsing']=True
            elif name=='--collapse-path':
                flags['collapse-path']=True
            elif name=='--enable-profiling':
                flags['enable-profiling']=True
            elif name=='--follow-symlinks':
                flags['follow-symlinks']=True
            elif name=='--help':
                flags['help']=True
            elif name=='--mouse':
                flags['mouse']=True
            elif name=='--no-color':
                flags['no-color']=True
            elif name=='--no-cross':
                flags['no-cross']=True
            elif name=='--no-delete':
                flags['no-delete']=True
            elif name=='--no-hidden':
                flags['no-hidden']=True
            elif name=='--no-prefix':
                flags['no-prefix']=True
            elif name=='--no-progress':
                flags['no-progress']=True
            elif name=='--no-spawn-shell':
                flags['no-spawn-shell']=True
            elif name=='--no-unicode':
                flags['no-unicode']=True
            elif name=='--non-interactive':
                flags['non-interactive']=True
            elif name=='--read-from-storage':
                flags['read-from-storage']=True
            elif name=='--reverse-sort':
                flags['reverse-sort']=True
            elif name=='--sequential':
                flags['sequential']=True
            elif name=='--show-annexed-size':
                flags['show-annexed-size']=True
            elif name=='--show-apparent-size':
                flags['show-apparent-size']=True
            elif name=='--show-disks':
                flags['show-disks']=True
            elif name=='--show-in-kib':
                flags['show-in-kib']=True
            elif name=='--show-item-count':
                flags['show-item-count']=True
            elif name=='--show-mtime':
                flags['show-mtime']=True
            elif name=='--show-relative-size':
                flags['show-relative-size']=True
            elif name=='--si':
                flags['si']=True
            elif name=='--summarize':
                flags['summarize']=True
            elif name=='--version':
