            elif name=='--write-config':
                flags['write-config']=True
            else:
                print(f"Error: unknown flag: {name}", file=sys.stderr)
                sys.exit(1)
        elif arg.startswith('-') and arg != '-':
            chars=arg[1:]
            j=0
            while j < len(chars):
                ch=chars[j]
                if ch=='h':
                    flags['help']=True
                    j+=1
                elif ch=='v':
                    flags['version']=True
                    j+=1
                elif ch=='c':
                    flags['no-color']=True
                    j+=1
                elif ch=='x':
                    flags['no-cross']=True
                    j+=1
                elif ch=='H':
                    flags['no-hidden']=True
                    j+=1
                elif ch=='p':
