            print(f"Error: error parsing regexp: {e}: `{pat}`", file=sys.stderr)
            sys.exit(1)
        cre = re.compile("^" + pat)
        ignore_regex_compiled.append((pat,cre))

    cwd=os.getcwd()
    ignore_exact=set()
    for entry in flags['ignore-dirs']:
        if not entry:
            continue
        if os.path.isabs(entry):
            ignore_exact.add(entry)
        else:
            abs_p = os.path.normpath(os.path.join(cwd, entry))
            ignore_exact.add(abs_p)

    inc_set=set([x.lower() for x in flags['type'] if x])
    exc_set=set([x.lower() for x in flags['exclude-type'] if x])

    since_dt=None
    since_is_date=False
    until_dt=None
    until_is_date=False
    if flags['since']:
        try:
            since_dt, since_is_date = parse_since_until(flags['since'])
        except ValueError as e:
            print(f"Error: invalid time filter: invalid --since value: {e}", file=sys.stderr)
            sys.exit(1)
    if flags['until']:
        try:
