                return
            nodes.append(node)
            if node.is_dir:
                for child in node.children:
                    if child.is_dir:
                        gather(child, cur_depth+1)
                    else:
                        if cur_depth+1 <= flags['depth']:
                            nodes.append(child)
        gather(root_node, 0)
        if nodes:
            root = nodes[0]
            rest = nodes[1:]
            def sz2(n):
                if n.is_dir:
