                size_val = n.apparent_total if flags['show-apparent-size'] else n.disk_total
            else:
                size_val = n.orig_asize if flags['show-apparent-size'] else (n.orig_dsize if n.orig_has_dsize else 0)
            print(format_line_no_flag(size_val, flags['si'], flags['show-in-kib'], flags['no-prefix'], n.full_path))
        sys.exit(0)

    children = root_node.children
    def sz3(c):
        if c.is_dir:
            return c.apparent_total if flags['show-apparent-size'] else c.disk_total
        else:
            return c.orig_asize if flags['show-apparent-size'] else (c.orig_dsize if c.orig_has_dsize else 0)
    children_sorted = sorted(children, key=lambda x: (sz3(x), x.name), reverse=not flags['reverse-sort'])
    for child in children_sorted:
        if child.is_dir:
            size_val = child.apparent_total if flags['show-apparent-size'] else child.disk_total
        else:
            size_val = child.orig_asize if flags['show-apparent-size'] else (child.orig_dsize if child.orig_has_dsize else 0)
        if child.is_dir:
