def get_help_text():
    return HELP_TEXT.format(cores=CORES)

def format_size_human(size, si=False):
    if si:
        if size < 1000:
            return f"{size} B"
        units = ["kB", "MB", "GB", "TB", "PB", "EB"]
        v = float(size)
        idx=-1
        while v >= 1000 and idx < len(units)-1:
            v/=1000
            idx+=1
        return f"{v:.1f} {units[idx]}"
    else:
        if size < 1024:
            return f"{size} B"
        units = ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB"]
        v=float(size)
        idx=-1
        while v>=1024 and idx < len(units)-1:
            v/=1024
            idx+=1
        return f"{v:.1f} {units[idx]}"

def format_size_kib(size, si=False):
    if si:
        v=size/1000.0
        return f"{v:.1f} kB"
    else:
        v=size/1024.0
