def parse_duration(s):
    if not s:
        raise ValueError(f'invalid duration format "{s}". Use combinations like 7d, 2h30m, 1y2mo')
    pattern = re.compile(r'(?P<value>\d+)(?P<unit>y|mo|w|d|h|m|s)')
    pos=0
    total=0
    found=False
    while pos < len(s):
        m=pattern.match(s,pos)
        if not m:
            raise ValueError(f'invalid duration format "{s}". Use combinations like 7d, 2h30m, 1y2mo')
        val=int(m.group('value'))
        unit=m.group('unit')
        found=True
        if unit=='y':
            total+=val*365*86400
        elif unit=='mo':
            total+=val*30*86400
        elif unit=='w':
            total+=val*7*86400
        elif unit=='d':
            total+=val*86400
        elif unit=='h':
            total+=val*3600
        elif unit=='m':
            total+=val*60
        elif unit=='s':
            total+=val
        pos=m.end()
    if not found:
        raise ValueError(f'invalid duration format "{s}". Use combinations like 7d, 2h30m, 1y2mo')
    return total

