def build_ignore_exact_set(ignore_dirs_list, cwd):
    result=set()
    for entry in ignore_dirs_list:
        if not entry:
            continue
        if os.path.isabs(entry):
            result.add(entry)
        else:
            abs_path = os.path.normpath(os.path.join(cwd, entry))
            result.add(abs_path)
    return result

def compile_ignore_patterns(pattern_list):
    compiled=[]
    for pat in pattern_list:
        if not pat:
            continue
        try:
            re.compile(pat)
        except re.error as e:
            print(f"Error: error parsing regexp: {e}: `{pat}`", file=sys.stderr)
            sys.exit(1)
        cre = re.compile("^" + pat)
        compiled.append((pat, cre))
    return compiled

def check_type_filter(filename, inc_set, exc_set):
    base = filename
    idx = base.rfind('.')
    if idx != -1:
        ext_go = base[idx:]
    else:
        ext_go = ""
    ext_trim = ext_go[1:].lower() if ext_go else ""
    if inc_set:
        if ext_trim not in inc_set:
            return False
    if exc_set:
        if ext_trim in exc_set:
            return False
    return True

def check_time_filter(mtime, since_dt, since_is_date, until_dt, until_is_date, max_age_sec, min_age_sec):
    mt = datetime.datetime.fromtimestamp(mtime, tz=datetime.timezone.utc)
    now = datetime.datetime.now(datetime.timezone.utc)
    if since_dt is not None:
        if mt < since_dt:
            return False
    if until_dt is not None:
        if until_is_date:
            end_of_day = until_dt + datetime.timedelta(days=1) - datetime.timedelta(microseconds=1)
            if mt > end_of_day:
                return False
        else:
            if mt > until_dt:
                return False
    if max_age_sec is not None:
        cutoff = now - datetime.timedelta(seconds=max_age_sec)
        if mt <= cutoff:
            return False
    if min_age_sec is not None:
        cutoff = now - datetime.timedelta(seconds=min_age_sec)
        if mt > cutoff:
            return False
    return True

def scan_recursive(current_path, flags, ignore_exact, ignore_regex, no_hidden, inc_set, exc_set, since_dt, since_is_date, until_dt, until_is_date, max_age_sec, min_age_sec, follow_symlinks, no_cross, root_dev, seen_inodes, is_initial=False):
    try:
        lst = os.lstat(current_path)
    except FileNotFoundError:
        print(f"Error: stat {current_path}: no such file or directory", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        lst = None

    if lst is None:
        mtime = int(time.time())
        node = Node(name=os.path.basename(current_path) or current_path, full_path=current_path, is_dir=True, mtime=mtime, flag='!')
        node.apparent_total = DIR_OWN_SIZE
        node.disk_total = DIR_OWN_SIZE
        node.item_count = 1
        return node

    is_dir = stat.S_ISDIR(lst.st_mode)
    is_symlink_l = stat.S_ISLNK(lst.st_mode)

    if not is_initial:
        if is_dir and not is_symlink_l:
            if current_path in ignore_exact:
                return None
            for _, cre in ignore_regex:
                if cre.search(current_path):
                    return None
            if no_hidden:
                base = os.path.basename(current_path)
                if base.startswith('.'):
                    return None
            if no_cross:
                if lst.st_dev != root_dev:
                    return None

    if is_dir and not is_symlink_l:
        mtime = int(lst.st_mtime)
        try:
            entries = os.listdir(current_path)
        except PermissionError:
            node = Node(name=os.path.basename(current_path) or current_path, full_path=current_path, is_dir=True, mtime=mtime, flag='!')
            node.apparent_total = DIR_OWN_SIZE
            node.disk_total = DIR_OWN_SIZE
            node.item_count = 1
            return node
        except FileNotFoundError:
            node = Node(name=os.path.basename(current_path) or current_path, full_path=current_path, is_dir=True, mtime=mtime, flag='!')
            node.apparent_total = DIR_OWN_SIZE
            node.disk_total = DIR_OWN_SIZE
            node.item_count = 1
            return node

        children=[]
        for ent in entries:
            child_path = os.path.join(current_path, ent)
            if no_hidden:
                if ent.startswith('.'):
                    try:
                        child_l = os.lstat(child_path)
                        if stat.S_ISDIR(child_l.st_mode):
                            continue
                    except:
                        continue
            try:
                child_lstat = os.lstat(child_path)
                child_is_dir = stat.S_ISDIR(child_lstat.st_mode)
            except:
                child_is_dir = False
                child_lstat = None

            if child_is_dir:
                if child_path in ignore_exact:
                    continue
                ignored=False
                for _, cre in ignore_regex:
                    if cre.search(child_path):
                        ignored=True
                        break
                if ignored:
                    continue
                if no_cross and child_lstat:
                    if child_lstat.st_dev != root_dev:
                        continue
            else:
                try:
                    mt = int(child_lstat.st_mtime) if child_lstat else int(time.time())
                except:
                    mt = int(time.time())
                if not check_time_filter(mt, since_dt, since_is_date, until_dt, until_is_date, max_age_sec, min_age_sec):
                    continue
                if not check_type_filter(ent, inc_set, exc_set):
                    continue

            child_node = scan_recursive(child_path, flags, ignore_exact, ignore_regex, no_hidden, inc_set, exc_set, since_dt, since_is_date, until_dt, until_is_date, max_age_sec, min_age_sec, follow_symlinks, no_cross, root_dev, seen_inodes, is_initial=False)
            if child_node is None:
                continue
            children.append(child_node)

        total_apparent = DIR_OWN_SIZE
        total_disk = DIR_OWN_SIZE
        total_count = 1
        for ch in children:
            total_apparent += ch.apparent_total
            total_disk += ch.disk_total
            total_count += ch.item_count

        flag=' '
        try:
            if len(os.listdir(current_path))==0:
                flag='e'
        except:
            pass
        for ch in children:
            if ch.flag == '!':
                flag='.'
                break

        node = Node(name=os.path.basename(current_path) or current_path, full_path=current_path, is_dir=True, mtime=int(lst.st_mtime), flag=flag, children=children)
        node.apparent_total = total_apparent
        node.disk_total = total_disk
        node.item_count = total_count
        node.flag = flag
        return node
    else:
        cur_lstat = os.lstat(current_path)
        is_symlink = stat.S_ISLNK(cur_lstat.st_mode)
        target_stat = None
        link_target = None
        if is_symlink:
            try:
                link_target = os.readlink(current_path)
            except:
                link_target = ""
            if follow_symlinks:
                try:
                    st = os.stat(current_path)
                    if not stat.S_ISDIR(st.st_mode):
                        target_stat = st
                except:
                    pass
        if is_symlink and target_stat is None:
            mtime = int(cur_lstat.st_mtime)
            asize = len(link_target) if link_target else 0
            node = Node(name=os.path.basename(current_path), full_path=current_path, is_dir=False, mtime=mtime, asize=asize, dsize=0, has_dsize=False, flag='@')
            node.apparent_total = asize
            node.disk_total = 0
            node.item_count = 1
            node.orig_asize = asize
            node.orig_dsize = 0
            node.orig_has_dsize = False
            return node
        st = target_stat if target_stat else cur_lstat
        if not stat.S_ISREG(st.st_mode):
            mtime = int(st.st_mtime)
            node = Node(name=os.path.basename(current_path), full_path=current_path, is_dir=False, mtime=mtime, asize=0, dsize=0, has_dsize=False, flag='@')
            node.apparent_total = 0
            node.disk_total = 0
            node.item_count = 1
            node.orig_asize = 0
            node.orig_dsize = 0
            node.orig_has_dsize = False
            return node
        mtime = int(st.st_mtime)
        asize = st.st_size
        blocks = getattr(st, 'st_blocks', 0)
        dsize = blocks*512
        has_dsize = dsize != 0
        ino = getattr(st, 'st_ino', 0)
        nlink = getattr(st, 'st_nlink', 1)
        has_ino = nlink > 1
        flag=' '
        if has_ino:
            flag='H'
            if ino in seen_inodes:
                node = Node(name=os.path.basename(current_path), full_path=current_path, is_dir=False, mtime=mtime, asize=asize, dsize=dsize, has_dsize=has_dsize, ino=ino, has_ino=True, flag=flag)
                node.apparent_total = 0
                node.disk_total = 0
                node.item_count = 1
                node.orig_asize = asize
                node.orig_dsize = dsize
                node.orig_has_dsize = has_dsize
                return node
            else:
                seen_inodes[ino]=True
        node = Node(name=os.path.basename(current_path), full_path=current_path, is_dir=False, mtime=mtime, asize=asize, dsize=dsize, has_dsize=has_dsize, ino=ino if has_ino else 0, has_ino=has_ino, flag=flag)
        node.apparent_total = asize if not has_ino or ino not in seen_inodes or True else 0
        # Actually for first occurrence, apparent_total should be asize, disk_total dsize if has_dsize else 0
        # For second, we already returned 0
        # So for first, set totals to asize and dsize
        if has_ino and ino in seen_inodes:
            # first occurrence already recorded, but we are in first branch? Actually first occurrence we just added to seen_inodes and continue to this node
            # So this node is first occurrence, with flag H
            node.apparent_total = asize
            node.disk_total = dsize if has_dsize else 0
        else:
            node.apparent_total = asize
            node.disk_total = dsize if has_dsize else 0
        node.item_count = 1
        node.orig_asize = asize
        node.orig_dsize = dsize
        node.orig_has_dsize = has_dsize
        # For first hardlink, we set apparent_total = asize (full), but earlier we wanted first to have full and second 0 for totals. That's what we have.
        # However for display in default mode, we want to show original size even for second? Let's keep display logic to use orig sizes.

        # For second occurrence we returned earlier with totals 0 but orig sizes preserved

        return node

def build_json_structure(node):
    lst=[]
    d={"name":node.name, "mtime":node.mtime}
    lst.append(d)
    for child in node.children:
        if child.is_dir:
            lst.append(build_json_structure(child))
        else:
            fd={"name":child.name}
            # Use orig sizes for JSON to keep full sizes even for hardlink second
            if child.orig_asize!=0:
                fd["asize"]=child.orig_asize
            if child.orig_has_dsize and child.orig_dsize!=0:
                fd["dsize"]=child.orig_dsize
            fd["mtime"]=child.mtime
            if child.has_ino and child.ino!=0:
                fd["ino"]=child.ino
                fd["hlnkc"]=True
            if child.flag=='@':
                fd["notreg"]=True
            lst.append(fd)
    return lst

def build_json_file(root_node):
    timestamp = int(time.time())
    header = {"progname":"gdu","progver":"dev","timestamp":timestamp}
    return [1,2,header, build_json_structure(root_node)]

def json_to_node(data_root_list, base_path=""):
    if not data_root_list or not isinstance(data_root_list, list):
        return None
    header_dict = data_root_list[0]
    name = header_dict.get("name","")
    mtime = header_dict.get("mtime", int(time.time()))
    full_path = name if os.path.isabs(name) else os.path.join(base_path, name) if base_path else name
    node = Node(name=name, full_path=full_path, is_dir=True, mtime=mtime, flag=' ')
    children=[]
    total_apparent=DIR_OWN_SIZE
    total_disk=DIR_OWN_SIZE
    total_count=1
    for item in data_root_list[1:]:
        if isinstance(item, dict):
            fname = item.get("name","")
            fpath = os.path.join(full_path, fname)
            asize = item.get("asize",0)
            dsize = item.get("dsize",0)
            has_dsize = "dsize" in item
            mtime_f = item.get("mtime", int(time.time()))
            ino = item.get("ino",0)
            has_ino = "ino" in item
            notreg = item.get("notreg",False)
            flag='@' if notreg else ' '
            child = Node(name=fname, full_path=fpath, is_dir=False, mtime=mtime_f, asize=asize, dsize=dsize, has_dsize=has_dsize, ino=ino, has_ino=has_ino, flag=flag)
            child.apparent_total=asize
            child.disk_total=dsize if has_dsize else 0
            child.orig_asize=asize
            child.orig_dsize=dsize
            child.orig_has_dsize=has_dsize
            child.item_count=1
            children.append(child)
            total_apparent+=asize
            total_disk+= (dsize if has_dsize else 0)
            total_count+=1
        elif isinstance(item, list):
            sub_node = json_to_node(item, base_path=full_path)
            if sub_node:
                children.append(sub_node)
                total_apparent+=sub_node.apparent_total
                total_disk+=sub_node.disk_total
                total_count+=sub_node.item_count
    node.children=children
    node.apparent_total=total_apparent
    node.disk_total=total_disk
    node.item_count=total_count
    if not children:
        node.flag='e'
    return node

def load_json_file(path):
    try:
        with open(path,'r') as f:
            content=f.read()
            data=json.loads(content)
            return data
    except FileNotFoundError:
        print(f"Error: opening input file: open {path}: no such file or directory", file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error: reading analysis: unexpected end of JSON input", file=sys.stderr)
        sys.exit(1)

def save_to_sqlite(db_path, root_node):
    try:
        if os.path.exists(db_path):
            os.remove(db_path)
    except:
        pass
    con=sqlite3.connect(db_path)
    cur=con.cursor()
    cur.execute("CREATE TABLE items (\n\t\tid          INTEGER PRIMARY KEY,\n\t\tparent_id   INTEGER REFERENCES items(id),\n\t\tname        TEXT NOT NULL,\n\t\tis_dir      INTEGER NOT NULL,\n\t\tsize        INTEGER NOT NULL,\n\t\tusage       INTEGER NOT NULL,\n\t\tmtime       INTEGER NOT NULL,\n\t\titem_count  INTEGER NOT NULL DEFAULT 1,\n\t\tmli         INTEGER NOT NULL DEFAULT 0,\n\t\tflag        TEXT NOT NULL DEFAULT ' '\n\t)")
    cur.execute("CREATE INDEX idx_items_parent_id ON items(parent_id)")
    cur.execute("CREATE INDEX idx_items_mli ON items(mli) WHERE mli != 0")
    cur.execute("CREATE TABLE metadata (\n\t\tkey   TEXT PRIMARY KEY,\n\t\tvalue TEXT\n\t)")
    cur.execute("INSERT INTO metadata (key,value) VALUES (?,?)", ("top_dir_path", root_node.full_path))
    next_id=1
    def insert_node(node, parent_id):
        nonlocal next_id
        cur_id=next_id
        next_id+=1
        is_dir_int=1 if node.is_dir else 0
        size = node.apparent_total
        usage = node.disk_total
        mli = node.ino if node.has_ino else 0
        flag = node.flag
        cur.execute("INSERT INTO items (id,parent_id,name,is_dir,size,usage,mtime,item_count,mli,flag) VALUES (?,?,?,?,?,?,?,?,?,?)",
                    (cur_id, parent_id, node.name, is_dir_int, size, usage, node.mtime, node.item_count, mli, flag))
        if node.is_dir:
            for child in node.children:
                insert_node(child, cur_id)
    insert_node(root_node, None)
    con.commit()
    con.close()

def load_from_sqlite(db_path):
    con=sqlite3.connect(db_path)
    cur=con.cursor()
    try:
        cur.execute("SELECT value FROM metadata WHERE key='top_dir_path'")
        row=cur.fetchone()
        top_path=row[0] if row else "/"
    except:
        top_path="/"
    cur.execute("SELECT id,parent_id,name,is_dir,size,usage,mtime,item_count,mli,flag FROM items ORDER BY id")
    rows=cur.fetchall()
    nodes={}
    root=None
    for r in rows:
        id_,parent_id,name,is_dir,size,usage,mtime,item_count,mli,flag = r
        is_dir_bool=bool(is_dir)
        node=Node(name=name, full_path="", is_dir=is_dir_bool, mtime=mtime, flag=flag)
        node.apparent_total=size
        node.disk_total=usage
        node.item_count=item_count
        node.ino=mli
        node.has_ino=mli!=0
        if is_dir_bool:
            node.asize=0
            node.dsize=0
            node.has_dsize=True
            node.orig_asize=0
            node.orig_dsize=0
            node.orig_has_dsize=True
        else:
            node.asize=size
            node.dsize=usage
            node.orig_asize=size
            node.orig_dsize=usage
            node.orig_has_dsize= (usage!=0)
            node.has_dsize= (usage!=0)
            if usage==0 and size!=0:
                node.has_dsize=False
                node.orig_has_dsize=False
            # For second hardlink with size 0 usage 0 flag H, orig sizes are 0, so we lose original size
            # But for display we need original size? In original db, second hardlink size 0 usage 0, so display would be 0 for default mode? But earlier we saw default mode for same dir hardlinks both showed full size with H, not 0.
            # So for db loaded, second hardlink should show 0 in default mode? Let's check original behavior when reading from db: earlier we had hardacross db reading? We didn't test hardlink db reading with default listing.
            # For now, we will keep as is.
        nodes[id_]=(node,parent_id)
        if parent_id is None:
            root=node
    for id_,(node,parent_id) in nodes.items():
        if parent_id is not None and parent_id in nodes:
            parent_node=nodes[parent_id][0]
            parent_node.children.append(node)
    if root:
        root.full_path=top_path
        def set_fp(node, base):
            for child in node.children:
                child.full_path=os.path.join(base, child.name)
                if child.is_dir:
                    set_fp(child, child.full_path)
        set_fp(root, root.full_path)
    con.close()
    return root

def list_devices():
    mounts=[]
    try:
        with open('/proc/mounts','r') as f:
            for line in f:
                parts=line.split()
                if len(parts)<4:
                    continue
                device=parts[0]
                mountpoint=parts[1]
                if not device.startswith('/dev/'):
                    continue
                mounts.append((device, mountpoint))
    except:
        pass
    results=[]
    for dev, mp in mounts:
        try:
            st=os.statvfs(mp)
            total=st.f_blocks*st.f_frsize
            free=st.f_bfree*st.f_frsize
            used=total-free
            results.append((dev,total,used,free,mp))
        except:
            continue
    return results

